// Budget, CPC, CTR and demand increments are explicit game assumptions.
export const AD_CHANNELS={etsy:{name:'Etsy Ads',cpc:.35,ctr:.022,boost:.65},google:{name:'Google Ads',cpc:.6,ctr:.018,boost:.75},local:{name:'Communication locale',cpc:.4,ctr:.025,boost:.9}};
export function normalizeMarketing(s){if(!s.marketing)s.marketing={history:[],spent:0,revenue:0};if(!Array.isArray(s.marketing.history)||s.marketing.history.length>100||!Number.isFinite(s.marketing.spent)||!Number.isFinite(s.marketing.revenue))throw Error('Historique publicitaire invalide.');const c=s.campaign;if(c.channel!=='none'&&!c.id){c.id='campaign-legacy';c.endAt=s.time+Math.max(1,c.days)*1440;c.nextCharge=s.time;c.impressions=0;c.clicks=0;c.inquiries=0;c.orders=0;c.revenue=0;c.target='all';}return s.marketing;}
export function archiveCampaign(s,reason){const c=s.campaign;if(c.channel==='none')return;s.marketing.history.unshift({...c,stoppedAt:s.time,reason});s.marketing.history=s.marketing.history.slice(0,80);c.channel='none';c.days=0;}
export function campaignBoost(s){const c=s.campaign;if(c.channel==='none'||!AD_CHANNELS[c.channel])return 0;if(c.channel==='etsy'&&!s.settings.useEtsy||c.channel==='local'&&!s.settings.useLocal||c.channel==='google'&&(!s.settings.useSite||s.website.stage!=='live'))return 0;return Math.min(1.5,AD_CHANNELS[c.channel].boost*Math.sqrt(c.daily/(c.channel==='local'?10:6)));}
export function attributeEnquiry(s,o,random){const c=s.campaign;if(c.channel==='none'||!campaignBoost(s))return;const channel=c.channel==='google'?'site':c.channel;if(o.channel!==channel||c.target!=='all'&&c.target!==o.product)return;if(random()<.6){o.campaignId=c.id;c.inquiries++;}}
export function attributeSale(s,o){if(!o.campaignId)return;const c=s.campaign.id===o.campaignId&&s.campaign.channel!=='none'?s.campaign:s.marketing.history.find(c=>c.id===o.campaignId);if(c){c.orders++;c.revenue+=o.settlement.gross;}s.marketing.revenue+=o.settlement.gross;}
